26	// ============================================================================
27	// TPUT: Remote write operation - write local data to remote NPU's memory
28	// Data flow: srcGlobalData (local GM) → stagingTileData (UB) → dstGlobalData (remote GM)
29	// Supports atomic operations: AtomicNone (default) or AtomicAdd
30	// ============================================================================
31	
32	// TPUT with atomic operation support (compile-time specified)
33	template <
34	    AtomicType atomicType = AtomicType::AtomicNone, typename GlobalDstData, typename GlobalSrcData, typename TileData,
35	    typename... WaitEvents>
36	PTO_INST RecordEvent
37	TPUT(GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, WaitEvents&... events)
38	{
39	    WaitAllEvents(events...);
40	    ::pto::comm::TPUT_IMPL<GlobalDstData, GlobalSrcData, TileData, atomicType>(
41	        dstGlobalData, srcGlobalData, stagingTileData);
42	    return {};
43	}
44	
45	// TPUT with runtime-specified atomic operation
46	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, typename... WaitEvents>
47	PTO_INST RecordEvent TPUT(
48	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, AtomicType atomicType,
49	    WaitEvents&... events)
50	{
51	    WaitAllEvents(events...);
52	    if (atomicType == AtomicType::AtomicAdd) {
53	        ::pto::comm::TPUT_IMPL<GlobalDstData, GlobalSrcData, TileData, AtomicType::AtomicAdd>(
54	            dstGlobalData, srcGlobalData, stagingTileData);
55	    } else {
56	        ::pto::comm::TPUT_IMPL<GlobalDstData, GlobalSrcData, TileData, AtomicType::AtomicNone>(
57	            dstGlobalData, srcGlobalData, stagingTileData);
58	    }
59	    return {};
60	}
61	
62	// TPUT with ping-pong double buffering (compile-time atomic type)
63	// Uses two staging tiles to overlap TLOAD and TSTORE for adjacent chunks
64	template <
65	    AtomicType atomicType = AtomicType::AtomicNone, typename GlobalDstData, typename GlobalSrcData, typename TileData,
66	    typename... WaitEvents>
67	PTO_INST RecordEvent TPUT(
68	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
69	    WaitEvents&... events)
70	{
71	    WaitAllEvents(events...);
72	    ::pto::comm::TPUT_IMPL<GlobalDstData, GlobalSrcData, TileData, atomicType>(
73	        dstGlobalData, srcGlobalData, pingTile, pongTile);
74	    return {};
75	}
76	
77	// ============================================================================
78	// TGET: Remote read operation - read remote NPU's data to local memory
79	// Data flow: srcGlobalData (remote GM) → stagingTileData (UB) → dstGlobalData (local GM)
80	// ============================================================================
81	
82	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, typename... WaitEvents>
83	PTO_INST RecordEvent
84	TGET(GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, WaitEvents&... events)
85	{
86	    WaitAllEvents(events...);
87	    ::pto::comm::TGET_IMPL(dstGlobalData, srcGlobalData, stagingTileData);
88	    return {};
89	}
90	
91	// TGET with ping-pong double buffering
92	// Uses two staging tiles to overlap TLOAD and TSTORE for adjacent chunks
93	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, typename... WaitEvents>
94	PTO_INST RecordEvent TGET(
95	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
96	    WaitEvents&... events)
97	{
98	    WaitAllEvents(events...);
99	    ::pto::comm::TGET_IMPL(dstGlobalData, srcGlobalData, pingTile, pongTile);
100	    return {};
101	}
102	
103	// ============================================================================
104	// TNOTIFY: Send flag notification to remote NPU
105	// Signal type must be int32_t
106	// ============================================================================
107	
108	template <typename GlobalSignalData, typename... WaitEvents>
109	PTO_INST void TNOTIFY(GlobalSignalData& dstSignalData, int32_t value, NotifyOp op, WaitEvents&... events)
110	{
111	    WaitAllEvents(events...);
112	    ::pto::comm::TNOTIFY_IMPL(dstSignalData, value, op);
113	}
114	
115	// ============================================================================
116	// TWAIT: Blocking wait until signal(s) meet comparison condition
117	// Used in conjunction with TNOTIFY for flag-based synchronization
118	// Signal type must be int32_t
119	//
120	// For signal matrix: Shape determines the 2D region to wait on. All signals must satisfy.
121	// ============================================================================
122	
123	template <typename GlobalSignalData, typename... WaitEvents>
124	PTO_INST void TWAIT(GlobalSignalData& signalData, int32_t cmpValue, WaitCmp cmp, WaitEvents&... events)
125	{
126	    WaitAllEvents(events...);
127	    ::pto::comm::TWAIT_IMPL(signalData, cmpValue, cmp);
128	}
129	
130	// ============================================================================
131	// TTEST: Non-blocking test if signal(s) meet comparison condition
132	// Returns true if condition is satisfied, false otherwise
133	//
134	// For signal matrix: Returns true only if ALL signals satisfy the condition.
135	// ============================================================================
136	
137	template <typename GlobalSignalData, typename... WaitEvents>
138	PTO_INST bool TTEST(GlobalSignalData& signalData, int32_t cmpValue, WaitCmp cmp, WaitEvents&... events)
139	{
140	    WaitAllEvents(events...);
141	    return ::pto::comm::TTEST_IMPL(signalData, cmpValue, cmp);
142	}
143	
144	// ============================================================================
145	// TGATHER: Gather operation - root collects data from all ranks
146	// Only the root needs to execute. Non-root ranks ensure source buffers are ready.
147	//
148	// Template parameter `engine` selects the backend:
149	//   CollEngine::AIV (default) — tile-based gather via TLOAD/TSTORE
150	//   CollEngine::CCU           — AIV triggers CKE gate; first variadic arg must be CcuTriggerContext
151	// ============================================================================
152	
153	template <
154	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalDstData, typename TileData,
155	    typename... Args>
156	PTO_INST RecordEvent
157	TGATHER(ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& stagingTileData, Args&... args)
158	{
159	    if constexpr (engine == CollEngine::AIV) {
160	        WaitAllEvents(args...);
161	        ::pto::comm::TGATHER_IMPL(parallelGroup, dstGlobalData, stagingTileData);
162	    } else if constexpr (engine == CollEngine::CCU) {
163	        static_assert(sizeof...(Args) >= 1, "TGATHER<CCU> requires CcuTriggerContext as first argument");
164	        ::pto::comm::TGATHER_CCU_IMPL<engine>(parallelGroup, dstGlobalData, stagingTileData, args...);
165	    }
166	    return {};
167	}
168	
169	// ============================================================================
170	// TGATHER (ping-pong): Gather with double buffering
171	// Uses two staging tiles to overlap TLOAD (next chunk) with TSTORE (current chunk).
172	// Only the root needs to execute.
173	// ============================================================================
174	
175	template <
176	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalDstData, typename TileData,
177	    typename... Args>
178	PTO_INST RecordEvent TGATHER(
179	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& pingTile, TileData& pongTile,
180	    Args&... args)
181	{
182	    if constexpr (engine == CollEngine::AIV) {
183	        WaitAllEvents(args...);
184	        ::pto::comm::TGATHER_IMPL(parallelGroup, dstGlobalData, pingTile, pongTile);
185	    } else if constexpr (engine == CollEngine::CCU) {
186	        static_assert(sizeof...(Args) >= 1, "TGATHER<CCU> requires CcuTriggerContext as first argument");
187	        ::pto::comm::TGATHER_CCU_IMPL<engine>(parallelGroup, dstGlobalData, pingTile, pongTile, args...);
188	    }
189	    return {};
190	}
191	
192	// ============================================================================
193	// TSCATTER: Scatter operation - root distributes data to all ranks
194	// Only the root needs to execute. Non-root ranks ensure destination buffers are allocated.
195	//
196	// Template parameter `engine` selects the backend:
197	//   CollEngine::AIV (default) — tile-based scatter via TLOAD/TSTORE
198	//   CollEngine::CCU           — AIV triggers CKE gate; first variadic arg must be CcuTriggerContext
199	// ============================================================================
200	
201	template <
202	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalSrcData, typename TileData,
203	    typename... Args>
204	PTO_INST RecordEvent
205	TSCATTER(ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData, Args&... args)
206	{
207	    if constexpr (engine == CollEngine::AIV) {
208	        WaitAllEvents(args...);
209	        ::pto::comm::TSCATTER_IMPL(parallelGroup, srcGlobalData, stagingTileData);
210	    } else if constexpr (engine == CollEngine::CCU) {
211	        static_assert(sizeof...(Args) >= 1, "TSCATTER<CCU> requires CcuTriggerContext as first argument");
212	        ::pto::comm::TSCATTER_CCU_IMPL<engine>(parallelGroup, srcGlobalData, stagingTileData, args...);
213	    }
214	    return {};
215	}
216	
217	// ============================================================================
218	// TSCATTER (ping-pong): Scatter with double buffering
219	// Uses two staging tiles to overlap TLOAD (next chunk) with TSTORE (current chunk).
220	// Only the root needs to execute.
221	// ============================================================================
222	
223	template <
224	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalSrcData, typename TileData,
225	    typename... Args>
226	PTO_INST RecordEvent TSCATTER(
227	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
228	    Args&... args)
229	{
230	    if constexpr (engine == CollEngine::AIV) {
231	        WaitAllEvents(args...);
232	        ::pto::comm::TSCATTER_IMPL(parallelGroup, srcGlobalData, pingTile, pongTile);
233	    } else if constexpr (engine == CollEngine::CCU) {
234	        static_assert(sizeof...(Args) >= 1, "TSCATTER<CCU> requires CcuTriggerContext as first argument");
235	        ::pto::comm::TSCATTER_CCU_IMPL<engine>(parallelGroup, srcGlobalData, pingTile, pongTile, args...);
236	    }
237	    return {};
238	}
239	
240	// ============================================================================
241	// TBROADCAST: Broadcast data from current NPU (root) to all ranks
242	// The calling NPU (parallelGroup.GetRootIdx()) is the root.
243	// Only the root needs to execute.
244	//
245	// Template parameter `engine` selects the backend:
246	//   CollEngine::AIV (default) — tile-based broadcast via TLOAD/TSTORE
247	//   CollEngine::CCU           — AIV triggers CKE gate; first variadic arg must be CcuTriggerContext
248	// ============================================================================
249	
250	template <
251	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalSrcData, typename TileData,
252	    typename... Args>
253	PTO_INST RecordEvent
254	TBROADCAST(ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& stagingTileData, Args&... args)
255	{
256	    if constexpr (engine == CollEngine::AIV) {
257	        WaitAllEvents(args...);
258	        ::pto::comm::TBROADCAST_IMPL(parallelGroup, srcGlobalData, stagingTileData);
259	    } else if constexpr (engine == CollEngine::CCU) {
260	        static_assert(sizeof...(Args) >= 1, "TBROADCAST<CCU> requires CcuTriggerContext as first argument");
261	        ::pto::comm::TBROADCAST_CCU_IMPL<engine>(parallelGroup, srcGlobalData, stagingTileData, args...);
262	    }
263	    return {};
264	}
265	
266	// ============================================================================
267	// TBROADCAST (ping-pong): Broadcast with double buffering
268	// Uses two staging tiles to overlap TLOAD (next chunk) with TSTORE (current chunk).
269	// Only the root needs to execute.
270	// ============================================================================
271	
272	template <
273	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalSrcData, typename TileData,
274	    typename... Args>
275	PTO_INST RecordEvent TBROADCAST(
276	    ParallelGroupType& parallelGroup, GlobalSrcData& srcGlobalData, TileData& pingTile, TileData& pongTile,
277	    Args&... args)
278	{
279	    if constexpr (engine == CollEngine::AIV) {
280	        WaitAllEvents(args...);
281	        ::pto::comm::TBROADCAST_IMPL(parallelGroup, srcGlobalData, pingTile, pongTile);
282	    } else if constexpr (engine == CollEngine::CCU) {
283	        static_assert(sizeof...(Args) >= 1, "TBROADCAST<CCU> requires CcuTriggerContext as first argument");
284	        ::pto::comm::TBROADCAST_CCU_IMPL<engine>(parallelGroup, srcGlobalData, pingTile, pongTile, args...);
285	    }
286	    return {};
287	}
288	
289	// ============================================================================
290	// TREDUCE: Reduce operation - root gathers and reduces data from all ranks
291	// Only the root needs to execute. Non-root ranks ensure source buffers are ready.
292	//
293	// Template parameter `engine` selects the backend:
294	//   CollEngine::AIV (default) — tile-based reduce via TLOAD + ReduceTiles + TSTORE
295	//   CollEngine::CCU           — AIV triggers CKE gate; first variadic arg must be CcuTriggerContext
296	// ============================================================================
297	
298	template <
299	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalDstData, typename TileData,
300	    typename... Args>
301	PTO_INST RecordEvent TREDUCE(
302	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& recvTileData,
303	    ReduceOp op, Args&... args)
304	{
305	    if constexpr (engine == CollEngine::AIV) {
306	        WaitAllEvents(args...);
307	        ::pto::comm::TREDUCE_IMPL(parallelGroup, dstGlobalData, accTileData, recvTileData, op);
308	    } else if constexpr (engine == CollEngine::CCU) {
309	        static_assert(sizeof...(Args) >= 1, "TREDUCE<CCU> requires CcuTriggerContext as first argument");
310	        ::pto::comm::TREDUCE_CCU_IMPL<engine>(parallelGroup, dstGlobalData, accTileData, recvTileData, op, args...);
311	    }
312	    return {};
313	}
314	
315	// ============================================================================
316	// TREDUCE (ping-pong): Reduce operation with ping-pong double buffering
317	// Only the root needs to execute. Non-root ranks ensure source buffers are ready.
318	// ============================================================================
319	
320	template <
321	    CollEngine engine = CollEngine::AIV, typename ParallelGroupType, typename GlobalDstData, typename TileData,
322	    typename... Args>
323	PTO_INST RecordEvent TREDUCE(
324	    ParallelGroupType& parallelGroup, GlobalDstData& dstGlobalData, TileData& accTileData, TileData& pingTileData,
325	    TileData& pongTileData, ReduceOp op, Args&... args)
326	{
327	    if constexpr (engine == CollEngine::AIV) {
328	        WaitAllEvents(args...);
329	        ::pto::comm::TREDUCE_IMPL(parallelGroup, dstGlobalData, accTileData, pingTileData, pongTileData, op);
330	    } else if constexpr (engine == CollEngine::CCU) {
331	        static_assert(sizeof...(Args) >= 1, "TREDUCE<CCU> requires CcuTriggerContext as first argument");
332	        ::pto::comm::TREDUCE_CCU_IMPL<engine>(
333	            parallelGroup, dstGlobalData, accTileData, pingTileData, pongTileData, op, args...);
334	    }
335	    return {};
336	}
337	
338	// ============================================================================
339	// TPUT_ASYNC: Asynchronous remote write (GM-to-GM via DMA engine).
340	// Build once with comm::BuildAsyncSession<engine>(), then pass to all calls.
341	// ============================================================================
342	
343	template <DmaEngine engine = DmaEngine::SDMA, typename GlobalDstData, typename GlobalSrcData, typename... WaitEvents>
344	PTO_INST AsyncEvent TPUT_ASYNC(
345	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, const AsyncSession& session, WaitEvents&... events)
346	{
347	    WaitAllEvents(events...);
348	    return ::pto::comm::TPUT_ASYNC_IMPL<engine>(dstGlobalData, srcGlobalData, session);
349	}
350	
351	#if defined(PTO_NPU_ARCH_A5) || defined(__CPU_SIM)
352	/**
