30	// Helper: Compare signal value with runtime comparison operator
31	PTO_INTERNAL bool CompareSignalRuntime(int32_t sigVal, int32_t cmpVal, WaitCmp cmp)
32	{
33	    if (cmp == WaitCmp::EQ)
34	        return sigVal == cmpVal;
35	    if (cmp == WaitCmp::NE)
36	        return sigVal != cmpVal;
37	    if (cmp == WaitCmp::GT)
38	        return sigVal > cmpVal;
39	    if (cmp == WaitCmp::GE)
40	        return sigVal >= cmpVal;
41	    if (cmp == WaitCmp::LT)
42	        return sigVal < cmpVal;
43	    if (cmp == WaitCmp::LE)
44	        return sigVal <= cmpVal;
45	    return false;
46	}
