48	} // namespace detail
49	
50	template <typename GlobalSignalData>
51	PTO_INTERNAL void TWAIT_IMPL(GlobalSignalData& signalData, int32_t cmpValue, WaitCmp cmp)
52	{
53	    const int64_t st0 = signalData.GetStride(GlobalTensorDim::DIM_0);
54	    const int64_t st1 = signalData.GetStride(GlobalTensorDim::DIM_1);
55	    const int64_t st2 = signalData.GetStride(GlobalTensorDim::DIM_2);
56	    const int64_t st3 = signalData.GetStride(GlobalTensorDim::DIM_3);
57	    const int64_t st4 = signalData.GetStride(GlobalTensorDim::DIM_4);
58	
59	    static_assert(std::is_same_v<typename GlobalSignalData::RawDType, int32_t>, "TWAIT: signal type must be int32_t");
60	
61	    // Get full 5-D shape and stride
62	    const int s0 = signalData.GetShape(GlobalTensorDim::DIM_0);
63	    const int s1 = signalData.GetShape(GlobalTensorDim::DIM_1);
64	    const int s2 = signalData.GetShape(GlobalTensorDim::DIM_2);
65	    const int s3 = signalData.GetShape(GlobalTensorDim::DIM_3);
66	    const int s4 = signalData.GetShape(GlobalTensorDim::DIM_4);
67	
68	    volatile __gm__ int32_t* basePtr = reinterpret_cast<volatile __gm__ int32_t*>(signalData.data());
69	
70	    // Wait until all signals satisfy the condition (full 5-D traversal)
71	    bool allSatisfied = false;
72	    uint32_t spin = 0;
73	    constexpr uint32_t kFenceInterval = 64;
74	    constexpr uint32_t kMaxSpinCount = 100000000; // Deadlock detection threshold
75	    while (!allSatisfied) {
76	        allSatisfied = true;
77	        for (int d0 = 0; d0 < s0 && allSatisfied; ++d0) {
78	            for (int d1 = 0; d1 < s1 && allSatisfied; ++d1) {
79	                for (int d2 = 0; d2 < s2 && allSatisfied; ++d2) {
80	                    for (int d3 = 0; d3 < s3 && allSatisfied; ++d3) {
81	                        for (int d4 = 0; d4 < s4; ++d4) {
82	                            const int64_t idx = d0 * st0 + d1 * st1 + d2 * st2 + d3 * st3 + d4 * st4;
83	                            __asm__ __volatile__("");
84	                            dcci((__gm__ void*)(basePtr + idx), cache_line_t::SINGLE_CACHE_LINE);
85	                            __asm__ __volatile__("");
86	                            if (!detail::CompareSignalRuntime(basePtr[idx], cmpValue, cmp)) {
87	                                allSatisfied = false;
88	                                break;
89	                            }
90	                        }
91	                    }
92	                }
93	            }
94	        }
95	        if (!allSatisfied) {
96	            PTO_ASSERT(spin < kMaxSpinCount, "TWAIT: possible deadlock detected, spin count exceeded maximum limit");
97	            if ((++spin % kFenceInterval) == 0) {
98	                pipe_barrier(PIPE_ALL);
99	            }
100	        }
101	    }
102	}
