58	// Process one full-tile chunk using intra-tile ping-pong (split tile into halves)
59	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, typename StrideT>
60	PTO_INTERNAL void TgetIntraPingPongOneChunk(
61	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int64_t remoteOff,
62	    int64_t localOff, int chunkCols, const StrideT& remoteChunkStride, const StrideT& localChunkStride,
63	    int rmtRowStride, int locRowStride)
64	{
65	    constexpr int kHalfRows = TileData::Rows / 2;
66	    using HalfTileData = Tile<
67	        TileData::Loc, typename TileData::DType, kHalfRows, TileData::Cols, TileData::BFractal, DYNAMIC, DYNAMIC,
68	        TileData::SFractal, TileData::SFractalSize, TileData::PadVal, TileData::Compact>;
69	
70	    HalfTileData pingHalf(kHalfRows, chunkCols);
71	    HalfTileData pongHalf(kHalfRows, chunkCols);
72	    const auto baseAddr = reinterpret_cast<std::uintptr_t>(stagingTileData.data());
73	    const auto halfAddr = reinterpret_cast<std::uintptr_t>(stagingTileData.data() + kHalfRows * TileData::Cols);
74	    TASSIGN_IMPL(pingHalf, baseAddr);
75	    TASSIGN_IMPL(pongHalf, halfAddr);
76	    pingHalf.SetKAligned(stagingTileData.GetKAligned());
