81	        dstGlobalData, srcGlobalData, pingHalf, pongHalf, pp, remoteOff, localOff, kHalfRows, chunkCols,
82	        remoteChunkStride, localChunkStride);
83	    TgetPingPongProcessChunk<GlobalDstData, GlobalSrcData, HalfTileData>(
84	        dstGlobalData, srcGlobalData, pingHalf, pongHalf, pp,
85	        remoteOff + static_cast<int64_t>(kHalfRows) * rmtRowStride,
86	        localOff + static_cast<int64_t>(kHalfRows) * locRowStride, kHalfRows, chunkCols, remoteChunkStride,
87	        localChunkStride);
88	    TgetPingPongFlush<GlobalDstData, HalfTileData>(dstGlobalData, pingHalf, pongHalf, pp, localChunkStride);
89	}
90	
91	// Process one (DIM_3 × DIM_4) slice: row/col sliding window within a single outer-dim group
92	template <typename GlobalDstData, typename GlobalSrcData, typename TileData, bool canSplitTile>
93	PTO_INTERNAL void TgetProcessSlice(
94	    GlobalDstData& dstGlobalData, GlobalSrcData& srcGlobalData, TileData& stagingTileData, int64_t rmtBase,
95	    int64_t locBase, const int (&rmtStep)[5], const int (&locStep)[5], int gShape3, int gShape4, int tileValidRow,
96	    int tileValidCol)
97	{
98	    using T = typename GlobalSrcData::RawDType;
99	    constexpr bool isDynamicRow = (TileData::ValidRow == DYNAMIC);
100	    constexpr bool isDynamicCol = (TileData::ValidCol == DYNAMIC);
101	    using DynShape = Shape<1, 1, 1, DYNAMIC, DYNAMIC>;
102	    using DynStride = Stride<DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC, DYNAMIC>;
103	    using SrcViewT = GlobalTensor<T, DynShape, DynStride, GlobalSrcData::layout>;
104	    using DstViewT = GlobalTensor<T, DynShape, DynStride, GlobalDstData::layout>;
105	    DynStride remoteChunkStride(rmtStep[0], rmtStep[1], rmtStep[2], rmtStep[3], rmtStep[4]);
106	    DynStride localChunkStride(locStep[0], locStep[1], locStep[2], locStep[3], locStep[4]);
107	
108	    for (int rowIdx = 0; rowIdx < gShape3; rowIdx += tileValidRow) {
