        dstGlobalData, srcGlobalData, pingHalf, pongHalf, pp,
        remoteOff + static_cast<int64_t>(kHalfRows) * rmtRowStride,
        localOff + static_cast<int64_t>(kHalfRows) * locRowStride, kHalfRows, chunkCols, remoteChunkStride,
