PTO_INTERNAL AsyncEvent TGET_ASYNC_IMPL(GlobalDstData& dst, GlobalSrcData& src, const AsyncSession& session,
                                        uint32_t peer)
{
    return TGET_ASYNC_IMPL<engine>(dst, src, session);
}

